use std::io::{self,BufRead};
use action_printer_core::emulator::Device;
use serde_json::{json,Value};
fn main(){let mut device=Device::default();for line in io::stdin().lock().lines(){let output=(||->Result<Value,String>{let line=line.map_err(|e|e.to_string())?;let input:Value=serde_json::from_str(&line).map_err(|e|e.to_string())?;if input["snapshot"]==true{return Ok(device.snapshot());}if let Some(n)=input["fault"].as_u64(){device.fault=n as u8;}if let Some(n)=input["busy_polls"].as_u64(){device.busy_polls=n as usize;}if let Some(n)=input["busy_after_stop"].as_u64(){device.busy_after_stop=n as usize;}if let Some(v)=input["reject_density"].as_bool(){device.reject_density=v;}if let Some(v)=input["lose_stop_ack"].as_bool(){device.lose_stop_ack=v;}let replies=if let Some(s)=input["feed"].as_str(){device.feed(&hex::decode(s).map_err(|e|e.to_string())?)?}else{vec![]};Ok(json!({"replies":replies.iter().map(hex::encode).collect::<Vec<_>>()}))})();println!("{}",match output{Ok(v)=>json!({"ok":true,"value":v}),Err(e)=>json!({"ok":false,"error":e})});}}
